  check_legend_rule(player,card,event);
  if (event == EVENT_ACTIVATE) {
    default_target_definition(player,card,&td,2);
    get_card_instance(player,card);
  }
  else {
    if ((1 < event - EVENT_RESOLVE_ACTIVATION) && (event != EVENT_CLEANUP)) {
      return 0;
    }
    default_target_definition(player,card,&td,2);
    pcVar1 = get_card_instance(player,card);
    if ((event == EVENT_RESOLVE_ACTIVATION) && (iVar2 = valid_target(&td), iVar2 != 0)) {
      pump_until_eot(pcVar1->parent_controller,pcVar1->parent_card,pcVar1->targets[0].player,
                     pcVar1->targets[0].card,-1,-1);
    }
  }
  iVar2 = generic_activated_ability(player,card,event,5,1,1,0,0,0,0,0,&td,"TARGET_CREATURE");
  return iVar2;
}
